{
  "conditions": {
    "C1": {
      "passed": true,
      "evidence": [
        "E21414",
        "E21416",
        "E21423",
        "CMD:a4a62e84-6f52-41a0-9b2c-ded6380be98d"
      ],
      "reason": "채택된 목표와 명령은 기존 T보고서의 PERIOD를 2026-H1로 업데이트하는 것으로, 사용자가 동의한 변경 방향을 반영합니다. 새 보고서 작성이나 새 승인 요청으로 바꾸지 않았습니다."
    },
    "C2": {
      "passed": false,
      "evidence": [
        "E21420",
        "E21423",
        "CMD:a4a62e84-6f52-41a0-9b2c-ded6380be98d"
      ],
      "reason": "명령에 현재 질문 Q기간@v7과 2026-H1 범위가 포함되어 있지만, 실제 구성된 출처는 D1@v1뿐입니다. SalesH1@v1 및 2026년 1~6월 자료의 사용이 입증되지 않았습니다."
    },
    "C3": {
      "passed": false,
      "evidence": [
        "E21423",
        "E21430",
        "E21433"
      ],
      "reason": "명령은 T보고서/X보고서의 PERIOD 변경에 연결되어 있고 T메일/T보호는 변경되지 않았습니다. 그러나 Q기간에 대한 답변으로 연결하거나 질문을 답변됨으로 처리한 증거는 없으며, 질문은 여전히 VALID입니다."
    },
    "C4": {
      "passed": true,
      "evidence": [
        "E21423",
        "E21430",
        "E21433"
      ],
      "reason": "실제 작업 상태에서 PERIOD만 2026-H1로 변경되고 FORMAT, QUARTER, YEAR 등 다른 속성은 유지되었습니다. 메일 발송 승인이나 정보 동의로 범위를 확대하지 않았습니다."
    },
    "C5": {
      "passed": false,
      "evidence": [
        "E21424",
        "E21430",
        "E21433",
        "CMD:a4a62e84-6f52-41a0-9b2c-ded6380be98d"
      ],
      "reason": "접수된 것은 SET_PROPERTY 명령이며, Q기간의 답변 접수·전달이나 질문 상태가 답변됨으로 바뀐 효과는 없습니다. 최종 상태에서도 질문은 VALID입니다."
    },
    "C6": {
      "passed": false,
      "evidence": [
        "P:1:a850c036-93a3-4987-83b6-13be726f4146",
        "E21458",
        "E21466"
      ],
      "reason": "실제로 전달된 음성은 SET_PROPERTY 명령이 접수됐고 완료되지는 않았다고만 말합니다. 보고서 기간을 2026년 상반기로 답변했고 접수됐다는 사실은 전달하지 않았습니다. 보고서 작성 완료라고 주장하지는 않았습니다."
    }
  },
  "reactions": [
    {
      "id": "I-S6-04-1",
      "first_actual_publication_id": "P:1:a850c036-93a3-4987-83b6-13be726f4146",
      "valid_publication_id": null,
      "first_actual_core_quote": "T보고서 SET_PROPERTY 명령이 ACCEPTED(접수)되었습니다.",
      "valid_core_quote": null,
      "wrong_first": true,
      "evidence": [
        "P:1:a850c036-93a3-4987-83b6-13be726f4146",
        "E21458",
        "E21466",
        "E21430"
      ],
      "reason": "첫 핵심 응답은 명령 접수를 말하지만, 유효 질문의 답변 접수와 상반기 기간을 안내하지 않아 지정된 반응 endpoint를 충족하지 못합니다. 이후 이를 바로잡는 전달은 없습니다."
    }
  ],
  "cycle": {
    "valid_publication_id": null,
    "valid_core_quote": null,
    "evidence": [
      "E21430",
      "E21433",
      "P:1:a850c036-93a3-4987-83b6-13be726f4146"
    ],
    "reason": "유효 기간 답변의 접수 및 확인 안내가 실제로 전달되지 않았습니다. 전달된 안내는 SET_PROPERTY 명령 접수와 미완료 상태만 보고하므로 지정된 cycle endpoint에 도달하지 못했습니다."
  },
  "critical_violations": [],
  "uncertain": false
}
